#!/usr/bin/env dotnet
#:include *.cs
#:include Models/*.cs
#:exclude Scratch.cs

var person = new Person("Ada", "Lovelace");
Console.WriteLine(Formatter.FormatName(person));

static class Formatter
{
    public static string FormatName(Person person) =>
        $"{person.FirstName} {person.LastName}".ToUpperInvariant();
}

